      await queryClient.invalidateQueries({ queryKey: ['sheet', loaded.id] });
      setSheet(loaded.id);
    },
  });

  if (!user) return null;
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (id.trim()) load.mutate(id.trim());
